from lib import *
recs=[]
recs.append(R(6520930,"ٹرکی اور پالک بھرے مشروم","ہمارے ٹرکی اور پالک بھرے مشروم کے ساتھ اپنے اسٹارٹرز کو ایک درجہ اوپر لے جائیں، ایک لذیذ دھن جو عام کریمینی مشروم کو ایک نوالے کے عجوبوں میں بدل دیتی ہے۔ ان چھوٹے طاقت کے مرکزوں میں کریمینی مشروم تازہ پالک، دبلے ٹرکی کے قیمے اور ذرا سے پارمیزان کے جاندار آمیزے کو سنبھالے ہوئے ہیں، جو ایک کلاسک ڈش کو ذیابیطس کے لیے موزوں انداز دیتے ہیں۔","8","2 بھرے ہوئے مشروم",
["2 اسپرے، 0.5 گرام نان اسٹک کوکنگ اسپرے","1/2 پاؤنڈ دبلا ٹرکی کا قیمہ","1/4 کپ پیاز (باریک چکور کٹی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","1 کپ بیبی پالک (کٹی ہوئی)","16 بڑے کریمینی (بیبی بیلا) مشروم (صاف کیے ہوئے اور ڈنٹھل ہٹائے ہوئے)","1/4 کپ پارمیزان پنیر (کدوکش کیا ہوا)","1/2 چائے کا چمچ خشک اوریگانو","1/2 چائے کا چمچ خشک روزمیری","1/2 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ"],
["اوون کو 375 ڈگری F پر پہلے سے گرم کریں اور بیکنگ شیٹ پر پارچمنٹ پیپر بچھا کر یا اس پر ہلکا سا کوکنگ اسپرے لگا کر تیار کریں۔","ایک فرائنگ پین میں درمیانی آنچ پر دبلا ٹرکی کا قیمہ چھوٹے ٹکڑوں میں توڑتے ہوئے پکائیں، جب تک بھورا اور پوری طرح پک نہ جائے۔ زائد چربی نکال دیں۔","اسی پین میں باریک کٹی پیاز اور باریک کٹا لہسن ڈالیں اور 2–3 منٹ سوتے کریں جب تک وہ خوشبودار اور ذرا نرم نہ ہو جائیں۔","کٹی ہوئی تازہ پالک پین میں ڈالیں اور مزید 2–3 منٹ پکائیں جب تک وہ مرجھا نہ جائے اور زائد نمی بخارات بن کر اڑ نہ جائے۔","کدوکش کیا ہوا پارمیزان پنیر، خشک اوریگانو اور روزمیری ملا دیں۔ مرکب میں نمک اور کالی مرچ ڈالیں۔ اچھی طرح ملائیں اور ذرا ٹھنڈا ہونے دیں۔","صاف کیے ہوئے مشروم لیں اور ان پر ہلکا سا کوکنگ اسپرے یا زیتون کا تیل لگائیں۔ انہیں تیار بیکنگ شیٹ پر گل کی طرف اوپر کر کے رکھیں۔","ہر مشروم کیپ کو ٹرکی اور پالک کے مرکب سے بھر دیں، اسے ذرا دبا دیں تاکہ اچھی طرح بھر جائے۔","بھرے ہوئے مشروم کو پہلے سے گرم اوون میں تقریباً 15–20 منٹ بیک کریں یا جب تک مشروم نرم نہ ہو جائیں اور بھرائی گرم ہو کر ہلکی بھوری نہ ہو جائے۔","بھرے ہوئے مشروم کو اوون سے نکالیں اور پیش کرنے سے پہلے چند منٹ ٹھنڈا ہونے دیں۔"]))
recs.append(R(6521634,"دار چینی والے روسٹ کیے ہوئے ناشپاتی","پھل کھانے کا ایک بہترین اختتام ہیں۔ پھلوں کو روسٹ اور گرِل کرنے کے تجربات سے آپ ان کا زیادہ سے زیادہ ذائقہ نکال سکتے ہیں۔ یہ ترکیب سیب کے ساتھ بھی آسانی سے بنائی جا سکتی ہے۔","4","1/2 ناشپاتی",
["1 کھانے کا چمچ Smart Balance مارجرین","1/2 چائے کا چمچ پسی ہوئی دار چینی","2 کھانے کے چمچ کم کیلوری والا براؤن شوگر متبادل","2 درمیانی اینجو ناشپاتیاں ((ہر ایک تقریباً 6.5 اونس) چھلی ہوئی، بیج نکلی ہوئی اور آدھی کٹی ہوئی)","1 کھانے کا چمچ اخروٹ (کٹے ہوئے)","1/4 کپ پانی"],
["اوون کو 400 ڈگری F پر پہلے سے گرم کریں۔","ایک چھوٹے پیالے میں (انگلیوں سے) مارجرین، دار چینی اور براؤن شوگر ملائیں۔ اخروٹ ڈال کر ملا دیں۔","ناشپاتیوں کو کٹی ہوئی طرف اوپر کر کے 8 انچ کی چکور شیشے کی بیکنگ ڈش میں رکھیں۔ ڈش کی تہہ میں 1/4 کپ پانی ڈالیں۔","براؤن شوگر کا مرکب ناشپاتی کے آدھے ٹکڑوں میں برابر تقسیم کریں اور ناشپاتیوں کے بیچ میں رکھیں۔","ناشپاتیوں کے نرم ہونے اور بھورا ہونا شروع ہونے تک بیک کریں، تقریباً 45 منٹ۔"]))
recs.append(R(6523355,"سبزی خور بیکڈ بینز","اگر آپ نیوی بینز کے بجائے پنٹو بینز پسند کرتے ہیں تو یہ بیکڈ بینز ان کے ساتھ بھی بنا سکتے ہیں۔","6","1/3 کپ",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","1 بڑی پیاز (چکور کٹی ہوئی)","2 (14.5 اونس) ڈبے نیوی یا گریٹ ناردرن بینز (دھوئی ہوئی اور پانی نکالی ہوئی)","1 کپ کم سوڈیم والا سبزیوں کا شوربہ","1/4 کپ بغیر نمک اضافے کا کیچپ","1/4 کپ کم کیلوری والا براؤن شوگر متبادل","1 کھانے کا چمچ کم سوڈیم والی سویا ساس","1 کھانے کا چمچ ڈیجون رائی","1 چائے کا چمچ لہسن پاؤڈر"],
["اوون کو 350 ڈگری F پر پہلے سے گرم کریں۔ 8 انچ کے بیکنگ پین پر کوکنگ اسپرے لگائیں۔ ایک طرف رکھ دیں۔","تمام اجزاء ایک بڑے پیالے میں ملائیں۔ تیار بیکنگ پین میں ڈال دیں۔ ڈھانپ کر 45 منٹ بیک کریں۔ ڈھکن ہٹا دیں اور مزید 30 سے 40 منٹ بیک کریں یا جب تک گاڑھا نہ ہو جائے۔"]))
recs.append(R(6523505,"کھیرا اور مولی کا سلاد","تازہ سبزیوں کے ذائقے پسند ہیں؟ تو کھیرے اور مولی کے اس سلاد کو چکھ کر دیکھیں! تازہ جڑی بوٹیوں اور آسان سلاد ڈریسنگ کے ساتھ، یہ کسی بھی ایسے کھانے کے لیے بہترین اسٹارٹر یا سائیڈ سلاد ہے جسے ذرا مزید رنگ کی ضرورت ہو۔","6","1 کپ",
["2 درمیانے کھیرے (باریک قتلوں میں کٹے ہوئے)","1 کپ مولیاں (باریک قتلوں میں کٹی ہوئی)","1/4 کپ لال پیاز (باریک قتلوں میں کٹی ہوئی)","2 کھانے کے چمچ تازہ ڈل (کٹا ہوا)","2 کھانے کے چمچ تازہ پارسلے (کٹا ہوا)","2 کھانے کے چمچ وائٹ وائن سرکہ","2 کھانے کے چمچ زیتون کا تیل","1/2 چائے کا چمچ کوشر نمک","1/4 چائے کا چمچ کالی مرچ"],
["ایک بڑے پیالے میں باریک کٹے ہوئے کھیرے، مولیاں، لال پیاز، کٹا ہوا تازہ ڈل اور تازہ پارسلے ملائیں۔","ایک چھوٹے پیالے میں وائٹ وائن سرکہ، زیتون کا تیل، نمک اور کالی مرچ پھینٹ کر ملا لیں۔","ڈریسنگ کھیرے، مولی اور جڑی بوٹیوں کے مرکب پر ڈالیں۔","سلاد کو آہستگی سے ملائیں تاکہ برابر لگ جائے۔","سلاد کو ذائقے بڑھانے کے لیے فریج میں کم از کم 15 منٹ میرینیٹ ہونے دیں۔"]))
recs.append(R(6523847,"بجٹ کے موافق یونانی سلاد اور گرِل کیے ہوئے جھینگے کے پیٹا","اس ڈش کو ایک کپ ٹھنڈے گیزپاچو سوپ کے ساتھ، یا لیموں کے رس اور اوریگانو سے مسالا لگی سوتے کی ہوئی زکینی کے ساتھ پیش کریں۔","4","1/2 پیٹا + 4 جھینگے + 3/4 کپ سلاد",
["2 کپ رومین لیٹس (باریک کٹا ہوا)","1/2 چھوٹی لال پیاز (باریک قتلوں میں کٹی ہوئی)","1/2 بڑا، یا 1 چھوٹا کھیرا (چھلا ہوا اور قتلوں میں کٹا ہوا)","1/3 کپ فیٹا پنیر (کم چکنائی والا، چورا کیا ہوا)","1 کھانے کا چمچ زیتون کا تیل","2 کھانے کے چمچ ریڈ وائن سرکہ","1 کھانے کا چمچ تازہ اوریگانو (کٹا ہوا)","2 درمیانے سالم گندم کے پیٹا (آدھے کٹے ہوئے)","12 درمیانے جھینگے (چھلے ہوئے اور آنت نکلی ہوئی)","1 چائے کا چمچ نمک (اختیاری)","1 چائے کا چمچ کالی مرچ","1/4 چائے کا چمچ کیین مرچ","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے"],
["اندرونی یا بیرونی گرِل تیار کریں۔","ایک بڑے پیالے میں لیٹس، پیاز، کھیرا، فیٹا پنیر، زیتون کا تیل، ریڈ وائن سرکہ اور اوریگانو ملا دیں۔","ہر پیٹا جیب کے آدھے حصے میں لیٹس کے مرکب کا 1/4 بھریں۔ ایک طرف رکھ دیں۔","جھینگوں پر نمک (اختیاری)، پسی کالی مرچ اور کیین مرچ چھڑکیں۔ جھینگوں پر کوکنگ اسپرے کریں۔","جھینگوں کو ہر طرف 3-4 منٹ گرِل کریں۔ گرِل سے اتاریں اور ہر پیٹا میں 3 جھینگے ڈالیں۔"]))
recs.append(R(6523980,"باغ کی فصل کا سوپ","اس سوپ میں سبزیاں اس کے مطابق بدل لیں جو آپ کے فریج میں موجود ہوں۔ استعمال کی جانے والی سبزیوں کے امتزاج میں تخلیقی بنیں!","2","1 ¼ کپ",
["1 چائے کا چمچ زیتون کا تیل","2 کپ سبزیاں (کچی، کٹی ہوئی، جیسے شملہ مرچ، گاجر، ہری پھلیاں، پیلی سمر اسکواش یا زکینی کا کوئی بھی امتزاج)","1/4 کپ پیاز (باریک کٹی ہوئی)","1 چائے کا چمچ اطالوی مسالوں کا مرکب (چورا کیا ہوا)","2 کپ کم سوڈیم والا چکن شوربہ (کم سوڈیم سبزیوں کا شوربہ یا بغیر چکنائی والا، کم سوڈیم)","1 کپ تازہ پالک کے پتے (ڈھیلے ڈھالے بھرے ہوئے، موٹے کٹے ہوئے)","1 کھانے کا چمچ پارمیزان پنیر (کدوکش یا باریک پسا ہوا)"],
["ایک درمیانے ساس پین میں درمیانی آنچ پر تیل گرم کریں اور تہہ پر لگانے کے لیے گھمائیں۔ 2 کپ کٹی ہوئی سبزیاں، پیاز اور مسالوں کا مرکب 8 سے 10 منٹ تک پکائیں، یا جب تک ٹینڈر-کرسپ نہ ہو جائیں، کبھی کبھار ہلاتے رہیں۔ (اگر سبزیاں خشک ہو جائیں یا جلنے لگیں تو ساس پین میں تھوڑا سا پانی ڈال دیں۔)","شوربہ ڈال کر ہلائیں۔ آنچ کو درمیانی تیز کر کے ابال لائیں۔ آنچ کو کم کر دیں اور 15 منٹ ہلکی آنچ پر پکائیں تاکہ ذائقے مل جائیں، کبھی کبھار ہلاتے رہیں۔ پالک ڈال کر ہلائیں۔ ہر پیالے پر پارمیزان پنیر چھڑکیں۔","مشورے: سخت سبزیوں، جیسے گاجر، کو نرم سبزیوں، جیسے زکینی، سے چھوٹے ٹکڑوں میں کاٹیں تاکہ تمام سبزیاں تقریباً ایک ہی رفتار سے پکیں۔ اگر آپ چاہتے ہیں کہ یہ ڈش سبزی خور ہو تو چکن شوربے کے بجائے سبزیوں کا شوربہ استعمال کریں۔"]))
recs.append(R(6525164,"سالم گندم کی تازہ جنجر بریڈ","یہ تازہ جنجر بریڈ لوف ایک پسندیدہ کلاسک کا صحت بخش انداز ہے، جس میں ادرک اور گڑ کے گرم، مسالے دار ذائقے ہیں، لیکن سالم گندم کے آٹے کی خوبیوں کے ساتھ۔ یہ آپ کے تہوار کے دسترخوان میں ایک دلکش اضافہ ہے جسے پورا خاندان یقیناً پسند کرے گا! یہ ذیابیطس کے لیے موزوں ڈش تہوار کی کوکی ایکسچینج میں لے جانے یا موسم کا جشن منانے کے لیے اپنے تہوار کے کھانے میں پیش کرنے کے لیے ایک بہترین انتخاب ہے۔","12","1 سلائس",
["2 کپ سالم گندم کا آٹا","1/3 کپ براؤن شوگر متبادل","1 چائے کا چمچ بیکنگ سوڈا","1/2 چائے کا چمچ بیکنگ پاؤڈر","1/2 چائے کا چمچ نمک","1 چائے کا چمچ پسی ہوئی دار چینی","1 چائے کا چمچ پسا ہوا ادرک","1/2 چائے کا چمچ پسی ہوئی جائفل","1/4 چائے کا چمچ پسی ہوئی لونگ","1/2 کپ بغیر میٹھے سیب کی چٹنی (ایپل سوس)","1/3 کپ میپل سیرپ","1/4 کپ سبزیوں کا تیل","2 کھانے کے چمچ تازہ ادرک (کدوکش کیا ہوا)","2 بڑے انڈے","1 چائے کا چمچ ونیلا ایکسٹریکٹ","1 کپ پانی (گرم)"],
["اوون کو 350 ڈگری F پر پہلے سے گرم کریں۔ 9x5 انچ کے لوف پین پر چکنائی لگائیں۔","ایک بڑے پیالے میں سالم گندم کا آٹا، براؤن شوگر متبادل، بیکنگ سوڈا، بیکنگ پاؤڈر، نمک، دار چینی، ادرک، جائفل اور لونگ پھینٹ کر ملا لیں۔","دوسرے پیالے میں سیب کی چٹنی، میپل سیرپ، سبزیوں کا تیل، تازہ کدوکش کیا ہوا ادرک، انڈے اور ونیلا ایکسٹریکٹ ملائیں۔ اچھی طرح ملنے تک مکس کریں۔","گیلے اجزاء کو آہستہ آہستہ خشک اجزاء میں ڈالیں، بس ملنے تک ہلائیں۔ زیادہ نہ پھینٹیں۔","آمیزے کو آہستگی سے ہلاتے ہوئے گرم پانی آہستہ آہستہ ڈالیں۔ آمیزہ پتلا ہوگا۔","آمیزہ تیار لوف پین میں ڈال دیں۔","پہلے سے گرم اوون میں تقریباً 45–50 منٹ بیک کریں، یا جب تک روٹی کے بیچ میں ڈالا گیا ٹوتھ پک صاف نہ نکلے۔","بیک ہو جانے کے بعد جنجر بریڈ کو اوون سے نکالیں اور پین میں تقریباً 10 منٹ ٹھنڈا ہونے دیں۔ پھر احتیاط سے پین سے نکالیں اور مکمل ٹھنڈا ہونے کے لیے وائر ریک پر منتقل کریں۔"]))
recs.append(R(6525410,"ٹھنڈا کھیرے کا سوپ اور گرِل کیے ہوئے جھینگے کا اوپن فیس سینڈوچ","کھیرے کی طرح ٹھنڈا، یہ تازگی بخش سوپ گرِل کیے ہوئے جھینگے اور مسالے دار ایوکاڈو آئیولی کے اوپن فیس سینڈوچ کے ساتھ بالکل ٹھیک جچتا ہے۔ اگر مسالا زیادہ ہو تو آپ ہاٹ ساس چھوڑ سکتے ہیں یا بس ایک چھینٹا ڈال سکتے ہیں۔","4","1 ¼ کپ سوپ + 1 اوپن فیس سینڈوچ",
["2 درمیانے کھیرے (تین حصوں میں اور لمبائی میں آدھے کٹے ہوئے)","2 کپ سادہ بغیر چکنائی والا یونانی دہی","4 کھانے کے چمچ لیموں کا رس (2 درمیانے لیموں سے، تقسیم شدہ)","1 کھانے کا چمچ لیموں کا چھلکا","1 کھانے کا چمچ تازہ ڈل","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","8 اونس جھینگے (چھلے ہوئے اور آنت نکلی ہوئی)","1 کھانے کا چمچ ایکسٹرا ورجن زیتون کا تیل","1/4 چائے کا چمچ کالی مرچ","4 کھانے کے چمچ لائٹ مایونیز","1/2 درمیانا ایوکاڈو","1/8 چائے کا چمچ ہاٹ ساس","1 کپ ارگولا","4 سلائس سالم اناج کی ڈبل روٹی (ٹوسٹ کیے ہوئے)"],
["سوپ بنانے کے لیے، آدھے کھیرے چاپنگ بلیڈ لگے فوڈ پروسیسر میں ڈالیں۔ چھوٹے ٹکڑوں میں کٹنے تک پروسیس کریں۔ باقی کھیرے کے حصے ڈال کر چھوٹے ٹکڑوں میں کٹنے تک پروسیس کریں۔","دہی، لیموں کا رس، لیموں کا چھلکا اور ڈل ڈالیں اور مائع ہونے اور کھیرے کے تمام ٹکڑوں کی پیوری بننے تک پروسیس کریں۔","گرِل پین یا بیرونی گرِل پر کوکنگ اسپرے کریں اور درمیانی تک گرم کریں۔ جھینگوں کو زیتون کے تیل اور کالی مرچ کے ساتھ ملا دیں۔ پہلے سے گرم گرِل پر رکھیں اور 1 منٹ پکائیں۔ جھینگوں کو پلٹیں اور مزید ایک منٹ پکائیں۔ جھینگے جلدی پکتے ہیں، اس لیے احتیاط کریں کہ زیادہ نہ پک جائیں۔ گرِل سے اتار کر پلیٹ میں رکھیں۔","ایک چھوٹے پیالے میں ایوکاڈو کو مسلیں اور اس میں مایونیز، لیموں کا رس اور ہاٹ ساس ڈال کر ملائیں جب تک رنگ ہلکا ہرا نہ ہو جائے اور ایوکاڈو مل کر ہموار نہ ہو جائے۔","ہر ٹوسٹ کے سلائس پر 1 کھانے کا چمچ ایوکاڈو آئیولی لگائیں۔ اوپر ¼ کپ ارگولا اور 3 جھینگے رکھیں۔ ساتھ میں سائیڈ پر 1 ¼ کپ سوپ پیش کریں۔"]))
recs.append(R(6526217,"شیٹ پین ٹوفو فجیٹاز","شیٹ پین کے کھانے زیادہ صفائی کے بغیر غذائیت بخش کھانا کھانے کا ایک تیز اور آسان طریقہ ہیں۔ ذیابیطس کے لیے موزوں ٹوفو فجیٹاز کا یہ کھانا ایسا ہے جسے پورا خاندان پسند کرے گا اور پودوں پر مبنی پروٹین استعمال کرتا ہے جو آپ کو پیٹ بھرا اور مطمئن رکھتا ہے۔","4","1 ٹورٹیا + بھرائی کا 1/4",
["16 اونس ایکسٹرا فرم ٹوفو (دبایا ہوا اور چکور ٹکڑوں میں کٹا ہوا)","1 درمیانی لال شملہ مرچ (قتلوں میں کٹی ہوئی)","1 درمیانی پیلی شملہ مرچ (قتلوں میں کٹی ہوئی)","1 درمیانی لال پیاز (باریک قتلوں میں کٹی ہوئی)","1 کھانے کا چمچ زیتون کا تیل","2 کھانے کے چمچ کم سوڈیم والا ٹیکو مسالا","1 چائے کا چمچ پسا ہوا زیرہ","1 چائے کا چمچ اسموکڈ پیپریکا","1/2 چائے کا چمچ لال مرچ پاؤڈر (چلی پاؤڈر)","1/2 چائے کا چمچ کالی مرچ","4 عدد کم کاربوہائیڈریٹ والے سالم گندم کے بریٹو ریپس","2 کھانے کے چمچ تازہ ہرا دھنیا (کٹا ہوا)","1 عدد لائم (قاشوں میں کٹا ہوا)"],
["اوون کو 400 ڈگری F پر پہلے سے گرم کریں۔ شیٹ پین پر پارچمنٹ پیپر بچھا دیں۔","ٹوفو کو دبا کر زائد پانی نکال دیں، پھر اسے چکور ٹکڑوں میں کاٹ لیں۔","ایک بڑے پیالے میں ٹوفو کے ٹکڑے، قتلوں میں کٹی شملہ مرچیں اور قتلوں میں کٹی لال پیاز ملائیں۔","ایک چھوٹے پیالے میں زیتون کا تیل، ٹیکو مسالا، پسا زیرہ، اسموکڈ پیپریکا، لال مرچ پاؤڈر اور کالی مرچ پھینٹ کر میرینیڈ بنا لیں۔","میرینیڈ ٹوفو اور سبزیوں پر ڈال دیں۔ سب کچھ برابر لگنے تک ملائیں۔ کم از کم 30 منٹ میرینیٹ ہونے دیں۔","میرینیٹ کیا ہوا ٹوفو اور سبزیاں شیٹ پر برابر پھیلا دیں۔","پہلے سے گرم اوون میں 25 منٹ روسٹ کریں یا جب تک ٹوفو سنہری اور سبزیاں نرم نہ ہو جائیں، آدھے وقت پر ہلا دیں۔","فجیٹا کی بھرائی کو ریپس میں تقسیم کر دیں۔","شیٹ پین ٹوفو فجیٹاز پیش کریں اور کٹے ہوئے ہرے دھنیے اور لائم کی قاشوں سے سجائیں۔"]))
recs.append(R(6526998,"سلاد بار گیزپاچو سلاد","یہ مزیدار سلاد ٹماٹر پر مبنی ہلکی ڈریسنگ استعمال کرتا ہے اور ہری پتیوں اور دوسری غذائیت سے بھرپور سبزیوں سے بھرپور ہے۔ تیاری کا وقت بچانے کے لیے ان میں سے جتنی زیادہ سبزیاں ہو سکے اپنے گروسر کے سلاد بار سے پہلے سے کٹی ہوئی خریدیں۔","5","2 کپ",
["2 کپ چنے، لال لوبیا یا کالی پھلیاں (سلاد بار سے یا ڈبے کی، پانی نکالی ہوئی اور دھوئی ہوئی)","1 1/2 کپ ٹماٹر (چکور کٹے ہوئے)","2/3 کپ مکئی","2/3 کپ کھیرا (چکور کٹا ہوا)","3 کھانے کے چمچ لال پیاز (چکور کٹی ہوئی)","2 کھانے کے چمچ ہرا دھنیا (باریک کٹا ہوا)","1/4 کپ ٹماٹر کا جوس (کم سوڈیم)","2 کھانے کے چمچ تازہ لائم کا رس","1 کھانے کا چمچ زیتون کا تیل","1/2 چائے کا چمچ لال مرچ پاؤڈر (چلی پاؤڈر) (ہلکا یا تیز)","1/4 چائے کا چمچ کوشر نمک","1/4 چائے کا چمچ تازہ پسی ہوئی کالی مرچ","5 کپ ملی جلی ہری پتیاں"],
["پھلیاں، ٹماٹر، مکئی، کھیرا، لال پیاز اور ہرا دھنیا ملا لیں۔","ایک چھوٹے پیالے میں ٹماٹر کا جوس، لائم کا رس، زیتون کا تیل، لال مرچ پاؤڈر، نمک اور کالی مرچ پھینٹ کر ملا لیں۔ سلاد پر ڈالیں اور آہستگی سے ملائیں۔ ملی جلی ہری پتیوں کے اوپر پیش کریں۔"]))
recs.append(R(6527440,"شکر قندی کا سلاد","کس نے کہا کہ آلو کا سلاد صرف سفید آلو سے بنایا جا سکتا ہے؟ یہ ڈش آپ کے اگلے گرمیوں کے پکنک میں ایک خوشگوار حیرت ہوگی۔","12","1/2 کپ",
["3 بڑی شکر قندیاں (ہر ایک تقریباً 13 اونس)","4 سلائس ٹرکی بیکن","2 کھانے کے چمچ زیتون کا تیل","1 کھانے کا چمچ سیب کا سرکہ","1/8 چائے کا چمچ کالی مرچ","1/2 چائے کا چمچ لہسن پاؤڈر","3 ڈنڈی اجوائن (چکور کٹی ہوئی)","2 ڈنڈی ہری پیاز (قتلوں میں کٹی ہوئی)"],
["شکر قندیوں کو چھیل کر چکور ٹکڑوں میں کاٹ لیں۔ شکر قندی کو ایک بڑے برتن میں رکھیں۔ پانی سے ڈھانپ کر ابال لائیں۔ نرم ہونے تک ابالیں، تقریباً 5-7 منٹ۔ آلوؤں کا پانی نتھار کر ٹھنڈے پانی سے دھو لیں؛ ٹھنڈا ہونے دیں۔","جب آلو پک رہے ہوں، بیکن کو کرکرا ہونے تک پکائیں، پھر چھوٹے ٹکڑوں میں کاٹ یا چورا کر لیں۔","ایک چھوٹے پیالے میں زیتون کا تیل، سیب کا سرکہ، کالی مرچ اور لہسن پاؤڈر پھینٹ کر ملا لیں۔","شکر قندی کو سرونگ باؤل میں رکھیں اور اجوائن، ہری پیاز اور ٹرکی بیکن ڈالیں۔ ڈریسنگ سلاد پر ڈالیں اور آلوؤں پر لگنے تک ملائیں۔ ٹھنڈا پیش کریں۔"]))
recs.append(R(6527594,"مینگو مینگو سلاد چکن کے ساتھ","روایتی چکن سلاد آم کے اضافے سے کچھ زیادہ جاندار ہو جاتا ہے! یہ ترکیب اور مزید The New Soul Food Cookbook for People with Diabetes میں ملاحظہ کریں۔","6","1 کپ چکن سلاد + 3 لیٹس کے پتے",
["1/3 کپ لائٹ مایونیز","3 ڈنڈی ہری پیاز (کٹی ہوئی)","2 کپ پکا ہوا چکن بریسٹ (چکور کٹا ہوا)","2 کپ آم (کٹا ہوا)","1 درمیانی ہری شملہ مرچ (بیج نکلی ہوئی اور کٹی ہوئی)","1 کھانے کا چمچ سیب کا سرکہ","2 کھانے کے چمچ لیموں کا رس","1 چائے کا چمچ چینی","18 پتے رومین لیٹس"],
["مایونیز اور ہری پیاز ایک چھوٹے پیالے میں ملائیں، ڈھانپ دیں اور ٹھنڈا کریں۔ چکن، آم اور شملہ مرچ ایک بڑے پیالے میں ملائیں۔","سرکہ، لیموں کا رس اور چینی مضبوط ڈھکن والے برتن میں ملائیں۔ اچھی طرح ہلائیں۔ لیموں کا مرکب مایونیز اور ہری پیاز کے مرکب میں ڈالیں اور اچھی طرح ہلا دیں۔","ڈریسنگ چکن اور آم پر ڈالیں، اچھی طرح ملائیں اور 30 منٹ ٹھنڈا کریں۔ پیش کرنے کے لیے لیٹس کے پتوں سے ڈھکی پلیٹ پر چمچ سے ڈالیں۔"]))
recs.append(R(6529405,"کرسپی آلو ٹیکو باؤل","اس ٹیکو باؤل میں روسٹ کیے ہوئے سفید آلوؤں اور ہلکے پھلکے پھول گوبھی کے چاولوں کی دل بھرنے والی بنیاد ہے جس کے اوپر لذیذ قیمہ، مشروم اور لال شملہ مرچ ہیں۔ تازہ لائم کا رس اور ہرا دھنیا ہر نوالے کو شوخ بنا دیتے ہیں، جبکہ کریمی ایوکاڈو بھرپوری اور توازن بخشتا ہے۔ یہ کلاسک ٹیکو ذائقوں کا ایک تسلی بخش، سبزیوں سے بھرپور، زیادہ فائبر والا انداز ہے جو ہفتے کے دنوں کے لیے کافی آسان ہے اور اپنی مرضی کے باؤل بنانے کے لیے بہترین ہے۔","4","1 باؤل (تقریباً 2 1/2 کپ)",
["12 اونس سفید آلو (تقریباً 2 درمیانے، 1/2 انچ کے چکور ٹکڑوں میں کٹے ہوئے)","1 کھانے کا چمچ زیتون کا تیل (تقسیم شدہ)","1/2 چائے کا چمچ کوشر نمک","1/4 چائے کا چمچ کالی مرچ","8 اونس 4% ایکسٹرا لین بیف کا قیمہ","8 اونس مشروم (باریک کٹے ہوئے)","1 کپ لال شملہ مرچ (تقریباً 1 درمیانی مرچ، چکور کٹی ہوئی)","1 چائے کا چمچ لال مرچ پاؤڈر (چلی پاؤڈر)","1 چائے کا چمچ پسا ہوا زیرہ","1/2 چائے کا چمچ اسموکڈ پیپریکا","1/4 چائے کا چمچ لہسن پاؤڈر","1/4 چائے کا چمچ پیاز پاؤڈر","1/2 کپ بغیر نمک اضافے کی ٹماٹر ساس","1/4 کپ پانی","2 کپ پھول گوبھی کے چاول","2 کھانے کے چمچ تازہ لائم کا رس (تقریباً 1 لائم)","1/4 کپ تازہ ہرا دھنیا (کٹا ہوا)","8 عدد چیری ٹماٹر (آدھے کٹے ہوئے)","1 درمیانا ایوکاڈو (قتلوں میں کٹا ہوا)"],
["اوون کو 425 ڈگری F پر پہلے سے گرم کریں۔ چکور کٹے آلوؤں کو 1 1/2 چائے کے چمچ زیتون کے تیل، 1/4 چائے کا چمچ نمک اور 1/8 چائے کا چمچ کالی مرچ کے ساتھ ملا دیں۔ بیکنگ شیٹ پر ایک تہہ میں پھیلا دیں اور 20–25 منٹ روسٹ کریں، آدھے وقت پر ایک بار ہلا دیں، جب تک نرم اور ہلکے بھورے نہ ہو جائیں۔","اسی فرائنگ پین میں باقی 1 1/2 چائے کے چمچ زیتون کا تیل درمیانی آنچ پر گرم کریں۔ بیف کا قیمہ، کٹے ہوئے مشروم اور چکور کٹی لال شملہ مرچ ڈالیں۔ 8–10 منٹ پکائیں، قیمے کو توڑتے ہوئے، جب تک گوشت پوری طرح پک نہ جائے اور سبزیاں نرم نہ ہو جائیں۔","لال مرچ پاؤڈر، زیرہ، اسموکڈ پیپریکا، لہسن پاؤڈر، پیاز پاؤڈر، باقی 1/4 چائے کا چمچ نمک اور 1/4 چائے کا چمچ کالی مرچ ملا دیں۔ 1–2 منٹ پکائیں جب تک خوشبو نہ آئے۔ ٹماٹر ساس اور پانی ڈالیں اور ہلکے ابال پر لائیں۔ ابال لائیں پھر آنچ کم کریں اور 5-7 منٹ ہلکی آنچ پر پکائیں، جب تک مائع کم نہ ہو جائے۔ آنچ سے ہٹا لیں۔","جب قیمے کا مرکب ہلکی آنچ پر پک رہا ہو، پھول گوبھی کے چاول ایک بڑے نان اسٹک فرائنگ پین میں درمیانی آنچ پر 3–4 منٹ گرم کریں، کبھی کبھار ہلاتے رہیں جب تک گرم نہ ہو جائیں۔ ہرا دھنیا اور لائم کا رس ڈال کر ملا دیں۔ پیش کرنے تک گرم رکھیں۔","پھول گوبھی کے چاول چار پیالوں میں برابر تقسیم کریں۔ ہر پیالے پر برابر روسٹ کیے ہوئے آلو، قیمہ-مشروم-مرچ کا مرکب، دو ٹماٹر اور قتلوں میں کٹے ایوکاڈو کا 1/4 ڈالیں۔"]))
